      if (maxAllowed >= 0 && (plan.capitalWordExact || plan.capitalWordMax) && matches.length > maxAllowed) {
        let seen = 0;
        answer = answer.replace(capitalPattern, word => (++seen <= maxAllowed ? word : word.toLowerCase()));
      }
