if(has('character')){x.strokeStyle='rgba(238,222,165,'+(0.22+q*.25)+')';x.lineWidth=4;x.beginPath();x.ellipse(W*.5,H*.4,W*.095,H*.13,0,0,Math.PI*2);x.stroke();x.fillStyle='rgba(35,255,170,'+(0.12+q*.12)+')';x.beginPath();x.arc(W*.46,H*.38,5+q*3,0,Math.PI*2);x.fill();x.beginPath();x.arc(W*.54,H*.38,5+q*3,0,Math.PI*2);x.fill();}
if(has('lighting')){x.fillStyle='rgba(235,215,150,'+(0.12+q*.1)+')';x.beginPath();x.arc(W*.78,H*.2,42+q*16,0,Math.PI*2);x.fill();}
