          confidence: distilled.confidence,
          summary: distilled.summary,
          procedure: distilled.procedure,
          sources: distilled.sources,
          agreement: distilled.agreement,
          responsePlan: distilled.responsePlan,
          semanticSelection: distilled.semanticSelection,
          semanticTriggerGroups: distilled.semanticTriggerGroups,
